from __future__ import annotations

import re
import uuid

from app.ports.storage import InvalidKeyError

_SAFE = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._\-/]{0,480}$")


def validate_key(key: str) -> str:
    """Keys are generated by us, but every adapter re-validates (no traversal, no odd bytes)."""
    if not _SAFE.match(key) or ".." in key.split("/") or "//" in key or key.endswith("/"):
        raise InvalidKeyError(f"invalid storage key: {key!r}")
    return key


def new_key(project_id: uuid.UUID, kind: str, ext: str) -> str:
    """Randomized, never derived from user input (SPEC §6.O)."""
    ext = re.sub(r"[^a-z0-9]", "", ext.lower())[:8] or "bin"
    return f"{project_id}/{kind}/{uuid.uuid4().hex}.{ext}"
